import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const Checkout = () => {
  const [form, setForm] = useState({ name: "", email: "", phone: "", address: "" });
  const cart = JSON.parse(sessionStorage.getItem("cart")) || [];

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const submitOrder = async () => {
    const subtotal = cart.reduce((sum, item) => sum + parseFloat(item.price), 0);
    const total = (subtotal + subtotal * 0.08 + (Math.floor(Math.random() * 5) + 3)).toFixed(2);

    const response = await fetch(`${API_BASE_URL}/api/orders`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: sessionStorage.getItem("userId"),
        items: cart,
        total,
        shipping_info: { address: form.address },
        buyer_name: form.name,
        buyer_email: form.email,
        buyer_phone: form.phone
      })
    });

    if (response.ok) {
      alert("✅ Order placed successfully!");
      sessionStorage.removeItem("cart");
      window.location.href = "/my-orders";
    } else {
      alert("❌ Order failed.");
    }
  };

  return (
    <div className="page-container">
      <Navbar />
      <div className="main-content checkout-form">
        <h2>Checkout</h2>
        <input type="text" name="name" placeholder="Full Name" onChange={handleChange} className="form-input" />
        <input type="email" name="email" placeholder="Email" onChange={handleChange} className="form-input" />
        <input type="text" name="phone" placeholder="Phone Number" onChange={handleChange} className="form-input" />
        <input type="text" name="address" placeholder="Shipping Address" onChange={handleChange} className="form-input" />
        <button onClick={submitOrder} className="submit-btn">Place Order</button>
      </div>
      <Footer />
    </div>
  );
};

export default Checkout;
